<?php foreach($record as $key=>$value): if(in_array($key,['id','azienda_id','creato_il','aggiornato_il','archiviato_at']))continue; if($key==='sopralluogo_id'&&$module==='preventivi'&&!$value)continue; if($module==='calendario'&&in_array($key,['intervento_id','sopralluogo_id'],true))continue; $label=$labels[$key]??ucfirst(str_replace('_',' ',$key)); $required=in_array($key,['cliente_id','titolo','numero','stato','tipo','inizio'],true)&&!($key==='tipo'&&$module!=='calendario')&&!($key==='inizio'&&$module!=='calendario'); $section=null;if($key==='cliente_id')$section='Cliente e luogo';if($module==='sopralluoghi'&&$key==='rilevazioni')$section='Valutazione tecnica';if($module==='sopralluoghi'&&$key==='pianificato_il')$section='Pianificazione';if($module==='preventivi'&&$key==='voci')$section='Servizi proposti';if($module==='preventivi'&&$key==='imponibile')$section='Riepilogo economico';if($module==='calendario'&&$key==='tipo')$section='Dettagli dell’evento'; ?>
<?php if($section): ?><div class="col-12 mt-2"><h2 class="h5 mb-0"><?= e($section) ?></h2></div><?php endif ?>
