<?php if($key==='sopralluogo_id'&&$module==='preventivi'): ?><input type="hidden" name="sopralluogo_id" value="<?= (int)$value ?>"><span class="form-control-plaintext">Creato dal sopralluogo #<?= (int)$value ?></span>
<?php elseif(in_array($key,['descrizione','note','rilevazioni','trattamenti_consigliati','prodotti','precauzioni','voci'],true)): ?><textarea class="form-control" id="<?= e($key) ?>" name="<?= e($key) ?>" rows="<?= $key==='voci'?4:3 ?>" <?= $required?'required':'' ?> placeholder="<?= e($help[$key]??'Aggiungi i dettagli utili.') ?>"><?= e((string)$value) ?></textarea>
<?php elseif(in_array($key,['cliente_id','sede_id','operatore_id','assegnato_a'],true)): ?><select class="form-select" id="<?= e($key) ?>" name="<?= e($key) ?>" <?= $required?'required':'' ?>><option value="">Seleziona…</option><?php $opts=$key==='cliente_id'?$clienti:($key==='sede_id'?$sedi:$utenti);foreach($opts as $opt):$oid=$opt['id'];$name=$opt['denominazione']??(($opt['cliente']??'')?$opt['cliente'].' · '.$opt['nome']:trim(($opt['nome']??'').' '.($opt['cognome']??''))); ?><option value="<?= (int)$oid ?>" <?= (string)$value===(string)$oid?'selected':'' ?>><?= e($name) ?></option><?php endforeach ?></select>
<?php elseif($key==='stato'||$key==='tipo'||$key==='modalita'): $options=$key==='stato'?($module==='sopralluoghi'?$stati['sopralluogo_stato']:($module==='preventivi'?$stati['preventivo_stato']:[])):($key==='tipo'?$stati['calendario_tipo']:['presenza'=>'In presenza','remoto'=>'Da remoto']); ?><select class="form-select" id="<?= e($key) ?>" name="<?= e($key) ?>" <?= $required?'required':'' ?>><?php foreach($options as $option=>$optionLabel): ?><option value="<?= e((string)$option) ?>" <?= (string)$value===(string)$option?'selected':'' ?>><?= e($optionLabel) ?></option><?php endforeach ?></select>
<?php else: $type=in_array($key,['pianificato_il','inizio','fine'],true)?'datetime-local':(str_contains($key,'validita')?'date':(in_array($key,['imponibile','iva','sconto','costo_stimato'])?'number':'text')); ?><input class="form-control" id="<?= e($key) ?>" name="<?= e($key) ?>" type="<?= $type ?>" value="<?= e((string)$value) ?>" <?= $required?'required':'' ?> <?= $type==='number'?'step="0.01" min="0"':'' ?>><?php endif ?></label>
<?php if(isset($help[$key])): ?><div class="help-text"><?= e($help[$key]) ?></div><?php endif ?>
<?php if(isset($errors[$key])): ?><div class="error"><?= e($errors[$key]) ?></div><?php endif ?></div>
<?php endforeach ?>
</div>
<?php if($module==='preventivi'): ?><div class="alert alert-light border mt-3 mb-0 d-flex justify-content-between align-items-center"><span>Totale indicativo, IVA inclusa</span><strong class="fs-5" data-quote-total>—</strong></div><?php endif ?>
<div class="actions mt-4"><button class="btn btn-primary btn-lg">Salva <?= e($title) ?></button><a class="btn btn-outline-secondary" href="/app/<?= e($module) ?>">Annulla</a></div></form>
